-- Gerado por scripts locais a partir de dados revisados; para editar, use /admin/midia ou regrave a linha com on conflict do update.

-- O Rei Leão (1994) · filme · 643 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'o-rei-leao-1994',
  'O Rei Leão',
  'The Lion King',
  'filme',
  1994,
  '{"Disney+"}'::text[],
  'L',
  '{}'::text[],
  5,
  'Livre pelo ClassInd. Nós subimos para 5 anos por causa da morte de Mufasa e das hienas: abaixo disso, só com o pai no sofá. Selo ClassInd anotado a partir das fichas de exibição; verificar no portal ClassInd antes de divulgar como certo.',
  9.3,
  3,
  '{"violencia": 2, "sexo": 0, "linguagem": 0, "drogas": 0, "consumismo": 0, "medo": 3, "valores_positivos": 5, "modelos_positivos": 4, "fe": 2, "mensagem": 5}'::jsonb,
  'O clássico da Disney sobre um filho que foge da própria responsabilidade e precisa voltar para assumir o lugar do pai. Morte em cena, mas com propósito.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Poucos filmes para crianças falam tão diretamente ao pai. O Rei Leão é a história de um menino que tem um pai forte, perde esse pai cedo, foge da própria culpa e precisa voltar para assumir o lugar que era dele. Se você tem um filho de cinco a dez anos, esse filme é quase um roteiro de conversa pronto sobre o que significa ser homem, ser filho e ser responsável por quem fica para trás."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata, sem contar o fim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Simba nasce herdeiro de Mufasa, o rei das Terras do Reino. O tio Scar, invejoso, arma uma tragédia que tira Mufasa de cena e convence o filhote de que a culpa é dele. Simba foge, cresce longe de casa com Timão e Pumba, aprende a filosofia do 'sem preocupações' e, anos depois, é chamado de volta por Nala e pelo macaco Rafiki para encarar o que deixou pendente. É um enredo simples, inspirado em Hamlet, e por isso mesmo atravessa gerações."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece na tela"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Violência moderada para a idade: a debandada de gnus, a queda de Mufasa, a luta final entre Simba e Scar e o ataque das hienas. Não há sangue, mas há morte real, e a criança entende que o pai do Simba morreu. O cemitério de elefantes, com as hienas rindo no escuro, é a cena que mais assusta os pequenos. Scar é um vilão convincente, frio e manipulador. Não há sensualidade além de uma brincadeira de adolescentes entre Simba e Nala durante a canção de amor, e não há linguagem imprópria."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O filme leva a sério a figura paterna. Mufasa corrige o filho com firmeza depois da aventura no cemitério, explica o Ciclo da Vida sem romantizar a morte e deixa um legado que o filho precisa carregar. A cena em que Simba olha para o reflexo na água e ouve que o pai vive dentro dele diz, em um minuto, o que muitos livros de paternidade levam capítulos para dizer. Há também a ideia dos antepassados que olham lá de cima, que um pai católico pode traduzir com naturalidade para a comunhão dos santos e para a esperança da vida eterna."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Hakuna Matata é a música mais cantada do filme, e é justamente a mentira que o roteiro desmonta: viver sem responsabilidade parece bom até a conta chegar. Se o seu filho sair cantando isso, você tem um gancho perfeito. O segundo ponto é a culpa: Scar faz a criança acreditar que causou a morte do pai. Vale conversar sobre a diferença entre culpa real e manipulação, porque criança pequena carrega culpa por coisas que não fez. Por fim, a morte de Mufasa pode render perguntas sobre a morte do próprio pai; responda com calma e sem fugir, como Mufasa faria."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A nota moral +3 vem do conjunto: autoridade paterna exercida com amor, pecado da inveja mostrado como destrutivo, retorno do filho ao dever e restauração da ordem no reino quando o rei legítimo assume o lugar. É uma parábola do filho pródigo com um detalhe a mais: aqui não é só o pai que espera, é o reino inteiro que sofre enquanto o herdeiro foge. Para um pai que quer ensinar que vocação é responsabilidade, e não privilégio, o filme entrega o recado."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A partir de cinco anos, com o pai junto nas duas cenas pesadas. Entre sete e dez anos, é o momento ideal: a criança já entende o peso da morte e da culpa e consegue conversar. Abaixo de cinco, a morte de Mufasa tende a virar pesadelo ou pergunta sem fim; não é proibido, mas é melhor esperar. A versão de 2019, em computação gráfica, é mais realista nas cenas de ataque e pede um ano a mais."}]}]}$body$::jsonb,
  'Mufasa morre no meio do filme e o filme não esconde isso da criança: Simba encontra o corpo do pai e se culpa. É a cena que decide a idade. A partir de 5 anos, com você ao lado, vira uma das melhores conversas sobre pai, morte e responsabilidade que um desenho já ofereceu. Scar é um vilão de verdade, as hienas assustam no cemitério de elefantes e a debandada de gnus tem tensão real. Não tem palavrão, não tem sensualidade, e a fé aparece de forma natural na ideia dos ''reis do passado'' que olham do céu. Hakuna Matata é charmoso, mas é exatamente a filosofia que o filme rejeita no fim: fugir do dever não resolve nada.',
  '{"Por que o Simba fugiu em vez de contar a verdade para a mãe dele?","O que o Mufasa quis dizer quando falou que ele continua vivo dentro do Simba?","Hakuna Matata parece bom, mas o que o Simba perdeu enquanto vivia sem responsabilidade?","O que você faria se alguém te culpasse por uma coisa que você não fez?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'O Rei Leão (1994) é para o seu filho? Ficha do pai',
  'Classificação Livre, mas com a morte de Mufasa em cena. Nota tripla do pai, conteúdo em bolinhas e o que conversar com seu filho depois do filme.'
)
on conflict (slug) do nothing;

-- Procurando Nemo (2003) · filme · 591 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'procurando-nemo',
  'Procurando Nemo',
  'Finding Nemo',
  'filme',
  2003,
  '{"Disney+"}'::text[],
  'L',
  '{}'::text[],
  4,
  'Livre pelo ClassInd. Nós indicamos a partir de 4 anos: a cena de abertura, com a perda da mãe e dos ovos, é rápida mas forte. Selo ClassInd anotado a partir das fichas de exibição; verificar no portal ClassInd antes de divulgar como certo.',
  9.0,
  3,
  '{"violencia": 1, "sexo": 0, "linguagem": 0, "drogas": 0, "consumismo": 0, "medo": 3, "valores_positivos": 5, "modelos_positivos": 5, "fe": 0, "mensagem": 5}'::jsonb,
  'Um pai superprotetor atravessa o oceano para recuperar o filho. O melhor filme da Pixar sobre o medo de deixar o filho crescer.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Procurando Nemo é o filme que todo pai de primeira viagem deveria ver antes do filho começar a andar. Não porque é fofo, mas porque conta a história de um homem que perdeu quase tudo numa noite, decidiu que nunca mais deixaria nada acontecer ao filho que sobrou e descobriu, do jeito mais difícil, que proteger demais também é uma forma de perder."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata, sem contar o fim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Marlin é um peixe-palhaço viúvo que cria Nemo, o único filho que sobreviveu a um ataque. No primeiro dia de aula, Nemo desafia o pai, nada até um barco e é capturado por um mergulhador. Marlin parte atrás dele pelo oceano, acompanhado por Dory, uma peixinha com perda de memória recente. Enquanto isso, Nemo tenta escapar de um aquário no consultório de um dentista em Sydney. As duas jornadas correm em paralelo e se encontram no fim."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece na tela"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A abertura é o único ponto realmente pesado: a barracuda ataca, a tela escurece e Marlin acorda sozinho com um ovo. Tudo sem sangue e em poucos segundos, mas a criança entende que a mãe morreu. Depois disso, a tensão é de aventura: a reunião de tubarões que tentam não comer peixe, o peixe-lanterna no escuro do fundo do mar, o campo de águas-vivas, a baleia, as gaivotas. A menina Darla, sobrinha do dentista, é a 'vilã' infantil que sacode o saquinho de peixe. Nada de linguagem imprópria ou sensualidade."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O filme mostra um pai que erra por excesso de amor e tem a honestidade de admitir. A frase de Dory, de que se nada acontecer com ele, nada vai acontecer com ele, resume o dilema de criar filho: segurança total é vida nenhuma. Nemo, por sua vez, aprende no aquário que coragem não é desobedecer o pai, é fazer a coisa certa quando ninguém está olhando. Os coadjuvantes dão exemplos de lealdade (Gill, que arrisca tudo pelo menino), de amizade (Dory) e até de paternidade exagerada ao contrário (o pai tartaruga Crush, que deixa o filho ser jogado pela corrente e confia)."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Pouca coisa. A desobediência inicial de Nemo é mostrada como erro e tem consequência imediata, o que é raro em desenho. Vale observar que o filme não tem referência explícita a fé; a esperança aqui é humana, baseada na persistência do pai e na ajuda dos outros. Crianças mais sensíveis podem ficar com medo do escuro depois da cena do peixe-lanterna, e algumas perguntam sobre a mãe do Nemo mais de uma vez. Responda direto: ela morreu, o pai cuidou dele sozinho e fez um bom trabalho."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral +3: o filme honra a paternidade, mostra o sacrifício do pai como coisa natural e não como heroísmo excepcional, e ensina que amor exige confiança. A viagem de Marlin é uma pequena peregrinação: ele atravessa o oceano, aceita ajuda de quem é diferente dele e chega transformado. Para o pai católico, é a lição de São José em forma de peixe: cuidar, proteger e, na hora certa, deixar o filho seguir a missão dele."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A partir de quatro anos, com você perto na abertura. Dos cinco aos nove é o auge, porque a criança se identifica com Nemo e começa a entender o Marlin. Para pais, o filme funciona em qualquer idade, e vale rever quando o filho começar a pedir mais autonomia. A continuação, Procurando Dory, é mais leve e pode entrar na mesma faixa."}]}]}$body$::jsonb,
  'A primeira cena mostra, em menos de dois minutos e sem sangue, a barracuda que tira a esposa e quase todos os ovos de Marlin. É forte para quem tem três anos e fica rápido demais para a criança de seis processar sozinha; vale pausar e explicar. Daí em diante o filme é uma aventura com tensão bem dosada: tubarões, águas-vivas, a boca da baleia, o aquário do dentista. Não há palavrão nem sensualidade. O tema central é a relação entre um pai que ama demais e protege demais e um filho que precisa de espaço para crescer, e o filme acerta nos dois lados.',
  '{"O Marlin cuidava do Nemo por amor, mas em que momento o cuidado virou medo?","O que o Nemo aprendeu no aquário que ele não teria aprendido em casa?","Por que a Dory conseguia ajudar o Marlin mesmo esquecendo tudo?","Quando você acha que o pai deve deixar o filho tentar sozinho, mesmo com medo?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'Procurando Nemo é para o seu filho? Ficha do pai',
  'Livre pelo ClassInd, indicado a partir de 4 anos pelo pai. Pai superprotetor, filho que quer crescer, cena de perda na abertura. Nota tripla e conversa.'
)
on conflict (slug) do nothing;

-- Toy Story (1995) · filme · 594 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'toy-story',
  'Toy Story',
  'Toy Story',
  'filme',
  1995,
  '{"Disney+"}'::text[],
  'L',
  '{}'::text[],
  4,
  'Livre pelo ClassInd. Indicamos a partir de 4 anos: os brinquedos mutilados do Sid assustam os menores por alguns minutos. Selo ClassInd anotado a partir das fichas de exibição; verificar no portal ClassInd antes de divulgar como certo.',
  9.1,
  3,
  '{"violencia": 1, "sexo": 0, "linguagem": 0, "drogas": 0, "consumismo": 1, "medo": 2, "valores_positivos": 5, "modelos_positivos": 4, "fe": 0, "mensagem": 5}'::jsonb,
  'O primeiro longa da Pixar: ciúme, orgulho e amizade entre um caubói e um astronauta que disputam o amor do mesmo menino.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Toy Story tem quase trinta anos e continua sendo a melhor aula sobre ciúme que você pode dar a um filho sem parecer sermão. O filme pergunta o que um homem faz quando deixa de ser o favorito, e a resposta de Woody na primeira metade é a resposta errada, mostrada com honestidade suficiente para a criança perceber."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata, sem contar o fim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Os brinquedos de Andy ganham vida quando ninguém está olhando. Woody, o caubói, lidera o quarto e é o preferido do menino até o aniversário em que chega Buzz Lightyear, um astronauta que acredita ser um patrulheiro espacial de verdade. O ciúme de Woody cresce, ele tenta um golpe baixo, a coisa sai do controle e os dois acabam fora de casa, no quarto do vizinho Sid, que gosta de explodir e desmontar brinquedos. Para voltar antes da mudança da família, precisam parar de brigar."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece na tela"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A violência é de brinquedo: Sid amarra um foguete em Buzz, derrete um soldado com lupa e tem um quarto cheio de bonecos remontados com peças de outros, que é a imagem mais assustadora do filme. Há uma briga curta entre Woody e Buzz num posto de gasolina. O cachorro Scud persegue os heróis. Nada de sangue, palavrão ou sensualidade. Há um momento em que Buzz, deprimido, veste um avental e toma chá numa brincadeira de meninas, o que rende riso, não constrangimento."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Woody erra por orgulho e paga pelo erro. O filme não abre exceção para o protagonista: os outros brinquedos o julgam, ele perde a confiança do grupo e só a recupera com ações, não com discurso. Buzz vive outra crise, a de descobrir que a identidade que construiu era ilusão, e encontra sentido novo em servir ao menino, que é o que ele sempre foi chamado a fazer. A amizade nasce quando os dois param de disputar e começam a cuidar um do outro. Para um pai, é material de sobra sobre humildade, vocação e lealdade."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O Sid. Ele é uma criança cruel, sem adulto por perto, e a vingança dos brinquedos no fim é assustadora para os pequenos (os brinquedos mutilados cercam o menino). Alguns pais preferem pular esse trecho com crianças de três anos. Há também o tema do consumismo nas entrelinhas: Buzz é o brinquedo novo da moda e desloca o antigo; vale uma frase sobre como a gente cuida do que já tem. Não há referência a fé no filme."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral +3. Orgulho e inveja são tratados como o que são, pecados que machucam o próprio culpado e os outros, e o caminho de volta passa por arrependimento concreto. A lição de Buzz, de que valor não está em ser extraordinário mas em ser fiel ao próprio lugar, é a melhor definição de vocação que um desenho animado já deu. E a casa de Andy, com mãe presente e filho que cuida do que é dele, é um retrato simples de família em ordem."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A partir de quatro anos, com atenção ao quarto do Sid. Dos cinco aos oito é perfeito, porque o ciúme entre irmãos e amigos é assunto do dia a dia nessa idade. Toy Story 2 e 3 sobem um pouco a carga emocional (abandono, crescimento, despedida) e cabem melhor a partir de seis anos; o terceiro filme fala do filho que vai embora para a faculdade e costuma fazer o pai chorar mais que a criança."}]}]}$body$::jsonb,
  'É um filme sobre ciúme. Woody era o brinquedo favorito de Andy, chega Buzz Lightyear e o caubói faz uma coisa feia por inveja, que dá errado e coloca os dois em perigo. A tensão vem de Sid, o vizinho que destrói brinquedos; o quarto dele, com bonecos remontados, assusta crianças de três anos por alguns minutos. Não há violência além de brinquedo sendo maltratado, nem palavrão, nem sensualidade. O que fica é a lição de humildade de Woody e a crise de Buzz ao descobrir que não é um herói de verdade.',
  '{"Por que o Woody ficou com ciúme do Buzz? Você já sentiu isso com um irmão ou amigo?","O Buzz ficou triste quando descobriu que era só um brinquedo. O que fez ele levantar de novo?","O Sid quebrava os brinquedos por diversão. O que a gente deve a quem é mais fraco que a gente?","No fim, o que valia mais para o Woody: ser o favorito ou cuidar do Andy?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'Toy Story é para o seu filho? Ficha do pai',
  'Livre pelo ClassInd, a partir de 4 anos pelo pai. Ciúme, humildade e amizade; o quarto do Sid é a única cena que assusta. Nota tripla e conversa.'
)
on conflict (slug) do nothing;

-- Divertida Mente (2015) · filme · 615 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'divertida-mente',
  'Divertida Mente',
  'Inside Out',
  'filme',
  2015,
  '{"Disney+"}'::text[],
  'L',
  '{}'::text[],
  6,
  'Livre pelo ClassInd. Indicamos a partir de 6 anos: antes disso a criança se diverte com as cores, mas não acompanha a ideia de emoções que disputam o controle. Selo ClassInd anotado a partir das fichas de exibição; verificar no portal ClassInd antes de divulgar como certo.',
  9.0,
  2,
  '{"violencia": 0, "sexo": 0, "linguagem": 0, "drogas": 0, "consumismo": 0, "medo": 2, "valores_positivos": 4, "modelos_positivos": 4, "fe": 0, "mensagem": 4}'::jsonb,
  'As emoções de uma menina de 11 anos ganham corpo e voz durante uma mudança de cidade. Útil para o pai que não sabe como falar de tristeza com o filho.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Divertida Mente é o filme que mais ajuda um pai a conversar com o filho sobre o que ele sente, e justamente por isso pede um pai do lado. A ideia é brilhante: as emoções de uma menina viram personagens, e a gente vê por dentro o que acontece quando uma criança perde a casa, os amigos e o time de hóquei de uma vez só."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata, sem contar o fim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Riley tem onze anos e se muda de Minnesota para São Francisco com os pais. Na cabeça dela, Alegria tenta manter tudo em ordem e empurra Tristeza para um canto, até que um acidente leva as duas para longe do painel de controle. Enquanto Raiva, Medo e Nojinho tentam comandar sozinhos, Riley vai perdendo as ilhas que sustentam a personalidade dela: família, amizade, honestidade, hóquei. Alegria e Tristeza precisam voltar antes que a menina tome uma decisão ruim."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece na tela"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nada de violência física, linguagem imprópria ou sensualidade. A tensão é emocional: ilhas da personalidade desabando, o amigo imaginário Bing Bong desaparecendo numa cena que faz adulto chorar, a menina apática na mesa de jantar, o roubo do cartão de crédito da mãe para comprar passagem de ônibus. O pai de Riley aparece distraído com o trabalho e, numa cena de jantar, perde a paciência e manda a filha para o quarto, o que o filme mostra como erro, não como modelo."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O filme desmonta a ideia de que uma família boa é uma família sempre alegre. Tristeza, a personagem que todo mundo quer esconder, é quem salva o dia, porque é ela que faz a menina pedir ajuda e os pais acolherem. Para um menino, isso vale ouro: chorar não é fraqueza, é sinal que avisa quem ama você. A família é retratada com pai e mãe presentes, imperfeitos e dispostos a consertar o que erraram. A memória, as lembranças e a identidade são tratadas com uma delicadeza rara em cinema para criança."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Dois pontos. O primeiro é filosófico: a história pode dar a impressão de que a pessoa é apenas a soma das emoções, sem vontade e sem razão que escolhem. O filme não afirma isso, e a decisão final de Riley é dela, mas vale o pai nomear: sentir é uma coisa, escolher é outra. O segundo é o pai de Riley, que o filme usa como exemplo de homem desatento; se você se reconhecer na cena do jantar, melhor rir e conversar do que se defender. A fuga de casa é mostrada como erro, mas crianças menores podem não entender o perigo real."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral +2: positivo, com um detalhe para conversar. A obra valoriza a família, a honestidade e o acolhimento da dor, e ensina que não existe pessoa completa sem tristeza, o que combina com a visão cristã de que o sofrimento tem lugar e sentido. Falta a dimensão da vontade e da graça, que o pai pode acrescentar: a gente não é prisioneiro das emoções, a gente as governa com a ajuda de Deus. Não há nada que contrarie a fé ou a família."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A partir de seis anos para aproveitar a ideia; antes disso a criança gosta das cores e das piadas, mas o filme não cumpre a função dele. Entre oito e doze anos é a idade ideal, especialmente para meninos que estão aprendendo a lidar com raiva e frustração. Para pais de pré-adolescentes que mudaram de escola ou de cidade, é quase obrigatório. A continuação, de 2024, acrescenta a Ansiedade e cabe melhor a partir de dez anos."}]}]}$body$::jsonb,
  'O filme se passa dentro da cabeça de Riley, uma menina de onze anos que se muda com os pais e perde o chão. Alegria, Tristeza, Raiva, Medo e Nojinho disputam o painel de controle. Não há violência, sensualidade ou linguagem imprópria. O que pode pesar é o tema: a menina fica deprimida, pensa em fugir de casa e o pai dela erra na hora de ouvir. A mensagem final, de que tristeza tem função e precisa ser acolhida, é valiosa para meninos que crescem ouvindo que homem não chora. O cuidado é com a ideia de que a pessoa é só o resultado das emoções, sem vontade; o filme não diz isso, mas a criança pode entender assim.',
  '{"Por que a Alegria não deixava a Tristeza tocar em nada? O que aconteceu quando ela finalmente deixou?","Quando a Riley ficou triste, o pai dela brigou. O que ele poderia ter feito diferente?","Qual emoção costuma mandar na sua cabeça? E o que você faz para não deixar ela decidir tudo?","A Riley quase fugiu de casa. O que fez ela voltar?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'Divertida Mente é para o seu filho? Ficha do pai',
  'Livre pelo ClassInd, a partir de 6 anos pelo pai. Emoções, mudança de cidade, tristeza que precisa de lugar. Nota tripla e perguntas para conversar.'
)
on conflict (slug) do nothing;

-- Bluey (2018) · serie · 609 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'bluey',
  'Bluey',
  'Bluey',
  'serie',
  2018,
  '{"Disney+","TV aberta"}'::text[],
  'L',
  '{}'::text[],
  2,
  'Livre pelo ClassInd. Indicamos a partir de 2 anos: é a série que mais ensina o pai enquanto o filho se diverte. Selo ClassInd anotado a partir das fichas de exibição; verificar no portal ClassInd antes de divulgar como certo.',
  9.5,
  4,
  '{"violencia": 0, "sexo": 0, "linguagem": 0, "drogas": 0, "consumismo": 0, "medo": 0, "valores_positivos": 5, "modelos_positivos": 5, "fe": 1, "mensagem": 5}'::jsonb,
  'Uma família de cachorros australianos, um pai que brinca de verdade e episódios de sete minutos que ensinam mais sobre paternidade que muito livro.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Se existe uma série que um pai deveria assistir junto com os filhos pequenos, é Bluey. Em sete minutos por episódio, a família Heeler, dois adultos e duas filhas, todos cachorros da raça blue heeler, resolve situações que acontecem na sua casa toda semana: a criança que não quer dormir, a irmã que não quer emprestar, o pai cansado depois do trabalho, a mãe que precisa de dez minutos de silêncio. E faz isso brincando."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bluey tem seis anos, Bingo tem quatro. O pai, Bandit, é arqueólogo; a mãe, Chilli, trabalha na segurança do aeroporto. Cada episódio parte de uma brincadeira inventada pelas meninas, quase sempre com os pais dentro: hotel, hospital, táxi, restaurante, piscina, mercado. Por trás da brincadeira há sempre uma lição pequena e concreta sobre paciência, perder, dividir, pedir desculpa, esperar a vez, cuidar de quem é menor. A série é australiana, mas as situações são universais."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece na tela"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nada que preocupe. Não há violência, nem mesmo a de desenho. Não há gritaria entre os pais, não há humor de deboche, não há sensualidade nem linguagem imprópria. Os conflitos são os de uma família normal e são resolvidos com conversa, firmeza e humor. Alguns episódios tocam em temas delicados com delicadeza: a avó que envelhece, um bebê que não veio, a mudança de casa, o pai que se chateia de verdade com as filhas. Tudo em tom adequado a uma criança de três anos, mas com camadas que o adulto percebe."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bandit é o retrato mais completo de pai presente que a televisão infantil já produziu. Ele brinca de corpo inteiro, deita no chão, deixa ser derrotado, cansa, reclama, e mesmo assim diz não quando precisa dizer não. Chilli é uma mãe firme e carinhosa, e o casamento dos dois aparece como parceria de verdade: eles conversam sobre as filhas, se revezam, se apoiam e, em mais de um episódio, mostram que o casal precisa de tempo a sós. Avós, tios e vizinhos completam uma rede de família extensa que faz falta em muito desenho moderno. A série também mostra as meninas errando e consertando, sem moral pesada no fim."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Quase nada, e o pouco que há é sobre o pai, não sobre a criança. Bandit parece ter tempo infinito, e é fácil terminar um episódio se sentindo culpado por não brincar tanto. Lembre que são sete minutos editados: a série mostra os melhores momentos de uma semana, não um dia inteiro. Alguns pais estranham o volume de brincadeira de faz de conta com regras mudando a cada minuto; a criança não estranha. A fé não aparece de forma explícita, mas valores como perdão, gratidão e cuidado com os mais fracos permeiam tudo."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral +4, a mais alta da régua: a série edifica a família. Pai e mãe casados, filhos que são prioridade sem ser o centro do universo, autoridade exercida com alegria, avós honrados, vizinhos acolhidos. Bandit encarna o líder servidor sem que ninguém use essa expressão: ele serve brincando e lidera dizendo não na hora certa. Para um pai que quer aprender a estar presente, vale mais que muito curso."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A partir de dois anos, sem restrição. É também uma das poucas séries infantis que o pai assiste sem sofrer, e muitos acabam vendo sozinhos. Entre três e sete anos é o auge. Depois dos oito, a criança pode achar infantil, mas os episódios sobre perder, mudar de casa e crescer continuam valendo. Assista junto e copie as brincadeiras: é para isso que a série existe."}]}]}$body$::jsonb,
  'Bluey é um desenho sobre brincar, e o personagem que mais brinca é o pai, Bandit. Episódios de sete minutos mostram a família Heeler em situações comuns: fila do banco, churrasco, hora de dormir, briga de irmãs. Não há violência, medo, linguagem imprópria ou sensualidade de nenhum tipo. O pai é presente, forte, brincalhão e casado com uma mãe igualmente presente; a casa tem regras, afeto e humor. O único ponto de atenção é o padrão: Bandit tem tempo e energia que muitos pais não têm, e alguns episódios podem fazer você se sentir em dívida. Use isso como inspiração, não como régua.',
  '{"Qual brincadeira do Bandit você quer fazer comigo neste fim de semana?","A Bluey e a Bingo brigam e depois fazem as pazes. Como vocês fazem isso em casa?","Por que o pai da Bluey diz não para algumas coisas mesmo brincando o tempo todo?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'Bluey é para o seu filho? Ficha do pai',
  'Livre pelo ClassInd, a partir de 2 anos. A série que mostra um pai presente brincando de verdade. Nota tripla, bolinhas e o que conversar.'
)
on conflict (slug) do nothing;

-- Peppa Pig (2004) · serie · 622 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'peppa-pig',
  'Peppa Pig',
  'Peppa Pig',
  'serie',
  2004,
  '{"Discovery Kids","Netflix","YouTube"}'::text[],
  'L',
  '{}'::text[],
  2,
  'Livre pelo ClassInd. Indicamos a partir de 2 anos, com uma ressalva que não é de idade: o Papai Pig é tratado como bobo em quase todo episódio, e isso pede comentário do pai. Selo ClassInd anotado a partir das fichas de exibição; verificar no portal ClassInd antes de divulgar como certo.',
  7.4,
  1,
  '{"violencia": 0, "sexo": 0, "linguagem": 1, "drogas": 0, "consumismo": 2, "medo": 0, "valores_positivos": 3, "modelos_positivos": 2, "fe": 0, "mensagem": 3}'::jsonb,
  'A porquinha mais famosa do mundo: episódios curtos, família unida e um pai que vira piada. Inofensiva, mas vale o pai assistir junto.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Peppa Pig está em todo lugar: na TV, no YouTube, na mochila, no tênis, no bolo de aniversário. É provavelmente o primeiro desenho que o seu filho vai pedir pelo nome. A boa notícia é que não há nada perigoso nele. A notícia que importa para o pai é outra: o desenho ensina, sem querer, um jeito de olhar para o pai de família que você vai querer corrigir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Peppa é uma porquinha de quatro anos que mora com o Papai Pig, a Mamãe Pig e o irmão George, de dois. Cada episódio tem cinco minutos e gira em torno de uma situação simples: pular em poças de lama, ir ao dentista, acampar, visitar os avós, brincar com os amigos da escolinha. O narrador comenta tudo, há risadinhas e gargalhadas em família, e o episódio quase sempre termina com todo mundo caindo no chão de tanto rir. A animação é simples de propósito, e as crianças adoram justamente por isso."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece na tela"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Zero violência, zero medo, zero sensualidade. A linguagem é limpa, mas a Peppa é frequentemente grosseira com o George e sarcástica com o pai, do tipo que uma criança de dois anos imita sem entender. O consumismo não está no episódio, está em volta dele: a marca é uma das mais licenciadas do planeta e o filho que assiste logo reconhece a porquinha na gôndola. Os episódios são tão curtos que a criança emenda dez sem perceber; o limite de tempo de tela é com você."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A família Pig é unida, come junto, visita os avós, brinca ao ar livre e resolve tudo com bom humor. Pai e mãe estão casados e presentes, o Papai Pig trabalha, a Mamãe Pig trabalha em casa, e as crianças têm rotina. A série ensina coisas práticas: escovar o dente, esperar a vez, cuidar do irmão menor, não ter medo do médico. A relação com os avós é um ponto alto, e há episódios bonitos sobre amizade e sobre perder uma brincadeira sem drama."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O Papai Pig. Ele é o motor cômico da série, e a piada é sempre a mesma: ele é gordo, atrapalhado, se perde, se acha ótimo em tudo e é corrigido pela mulher e pelos filhos. Não há maldade, mas o padrão se repete tanto que a criança absorve a ideia de que pai é uma figura cômica e não uma autoridade. Some a isso a Peppa mandona, que manda no irmão e às vezes na mãe, e você tem um modelo de família onde a criança pequena é o centro e o pai é a piada. Muitos pais relatam que o filho passou a dizer 'papai bobo' depois de assistir, e algumas famílias no exterior tiraram a série do ar em casa por isso. Nossa posição é mais simples: assista junto e comente."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral +1: inofensiva, com algum bom exemplo (família unida, avós honrados, rotina) e um ponto torto fácil de corrigir na conversa (a autoridade paterna ridicularizada). Não há nada contrário à fé ou à família. O que falta é um pai respeitado, e isso você supre em casa: quando o Papai Pig cair na lama, ria junto e depois mostre o que o pai faz quando ninguém está rindo."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A partir de dois anos, em doses pequenas e com o pai por perto nas primeiras semanas. Aos cinco a criança costuma cansar sozinha. Se você perceber o filho imitando o tom da Peppa com o irmão ou chamando você de bobo, não precisa proibir: nomeie, corrija e ofereça Bluey, que faz o mesmo serviço com um pai muito melhor."}]}]}$body$::jsonb,
  'Peppa Pig é segura em todo sentido: sem violência, sem medo, sem sensualidade, sem palavrão. Família com pai, mãe, irmão e avós, rotina doméstica e episódios de cinco minutos. O que pede atenção é o padrão de humor: o Papai Pig é gordo, desastrado, erra o caminho, cai na lama e é corrigido pela esposa e pelas crianças em quase todo episódio. A Peppa é mandona e às vezes mal-educada com o irmão e com o pai. Nada disso é grave, mas criança de dois anos repete o que vê, e muitos pais notam o filho chamando o pai de bobo depois de uma temporada. O volume de produtos licenciados também é enorme.',
  '{"O Papai Pig erra bastante, mas o que ele faz de bom pela família?","A Peppa às vezes fala de um jeito feio com o George. Como a gente fala com irmão menor aqui em casa?","Qual episódio você mais gosta? O que a família da Peppa fez junto nele?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'Peppa Pig é para o seu filho? Ficha do pai',
  'Livre e segura, a partir de 2 anos. Família unida, mas pai tratado como bobo e filha mandona pedem o pai do lado. Nota tripla e perguntas.'
)
on conflict (slug) do nothing;

-- Round 6 (2021) · serie · 661 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'round-6',
  'Round 6',
  'Squid Game',
  'serie',
  2021,
  '{"Netflix"}'::text[],
  '18',
  '{"violência extrema","linguagem imprópria","conteúdo sexual"}'::text[],
  18,
  '18 anos pelo ClassInd, e nós concordamos: não é para adolescente, por mais que a escola inteira fale dela. Descritores anotados da ficha da plataforma; verificar no portal ClassInd.',
  8.2,
  -3,
  '{"violencia": 5, "sexo": 3, "linguagem": 4, "drogas": 2, "consumismo": 1, "medo": 5, "valores_positivos": 1, "modelos_positivos": 1, "fe": 1, "mensagem": 1}'::jsonb,
  'Centenas de endividados disputam uma fortuna em brincadeiras infantis onde perder significa morrer. Bem feita, brutal e só para adulto formado.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Round 6 entra nesta lista por um motivo que não é recomendação: ela é a série que mais chegou a crianças brasileiras sem passar pela sala de estar. Em 2021 virou fantasia de Halloween, brincadeira de recreio, filtro de rede social e jogo de celular para a faixa de oito a doze anos. Se o seu filho está na escola, ele sabe o que é a boneca gigante que canta, mesmo que nunca tenha visto um episódio. Esta ficha serve para o pai saber do que se trata, decidir e conversar."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata, sem contar o fim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Seong Gi-hun, um motorista endividado e pai ausente da filha, aceita o convite de um desconhecido para participar de uma competição secreta. Quatrocentas e cinquenta e seis pessoas, todas afundadas em dívida, disputam um prêmio bilionário em seis rodadas de brincadeiras infantis coreanas. Na primeira rodada descobrem que quem perde é executado. A série acompanha as alianças, as traições e o desmoronamento moral dos participantes, enquanto um policial investiga por dentro quem organiza o jogo."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece na tela"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Violência no grau máximo da nossa escala: execuções em massa a tiro, degola, corpos arrastados, cremação, uma rodada inteira de violência corpo a corpo no escuro. Nudez e uma cena de sexo explícita em um banheiro. Palavrão constante na dublagem e na legenda. Suicídio consumado, alcoolismo, tráfico de órgãos, apostas. Um personagem pastor é retratado como hipócrita que reza enquanto trai, e a única oração sincera da série parte de um personagem que também mata. A trilha com músicas clássicas sobre matança é o tipo de contraste que fica na cabeça."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que a série tem de bom (para adulto)"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A produção é excelente e a crítica é séria: a dívida como forma de escravidão moderna, o desprezo dos ricos pelos pobres transformado em espetáculo, a facilidade com que gente comum abandona a consciência quando a vida está em jogo. O protagonista é um homem que falhou como pai e como filho e tenta, de modo torto, consertar. Há momentos de sacrifício real, sobretudo entre duas mulheres e entre um velho e o protagonista. Nada disso justifica mostrar para um adolescente; justifica o pai saber do que se trata."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa, e muito"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Primeiro, a banalização: a série foi desenhada para ser memeável, e a imagem das brincadeiras mortais virou produto para criança em questão de semanas. Segundo, o niilismo: quase todo personagem decente morre, e a mensagem que fica para quem tem quinze anos é que o mundo é um jogo armado em que bondade é fraqueza. Terceiro, o retrato da fé como hipocrisia. Quarto, e mais concreto: versões 'para crianças' do jogo circulam no YouTube e em jogos de celular com as mesmas brincadeiras sem o sangue, e são a porta de entrada para a série original."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral -3: muito problemática. A série normaliza a violência como entretenimento, trata a fé como fachada e deixa pouco espaço para esperança, ainda que a intenção dos autores seja denunciar o sistema. Um adulto formado pode assistir como quem lê um relatório sobre o desespero humano e tirar lições sobre dívida, dignidade e paternidade ausente. Um adolescente absorve o espetáculo e perde a denúncia. Nossa recomendação é clara: não é para quem mora na sua casa e tem menos de dezoito anos, e se você for ver, veja sabendo o que vai encontrar."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que fazer na prática"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Não adianta fingir que a série não existe: ela já chegou ao seu filho pelo recreio. Pergunte o que ele sabe, explique por que é para adultos sem fazer mistério, confira os jogos de celular instalados e o histórico do YouTube Kids, e ofereça aventura de verdade no lugar. Se ele já viu episódios escondido, a conversa precisa ser sobre confiança, não só sobre violência. E se a dívida da série bateu perto de casa, essa é a hora de falar de dinheiro com os filhos como homem, sem vergonha."}]}]}$body$::jsonb,
  'A série é exatamente o que dizem: brincadeiras de criança (batatinha frita, cabo de guerra, bolinha de gude) transformadas em execução em massa, com sangue, tiros à queima-roupa e corpos empilhados. Há nudez e uma cena de sexo explícita, palavrão constante, suicídio, tráfico de órgãos e um cristão retratado como hipócrita. A ClassInd classificou em 18 anos e a nota está certa. O problema para o pai não é a série em si, que é bem produzida e tem uma crítica real ao desespero da dívida, e sim o fato de que ela virou brincadeira de pátio de escola, com fantasia, jogo de celular e versão para crianças no YouTube. Seu filho de dez anos conhece a série mesmo sem ter visto. A ficha existe para você saber o que ele está ouvindo.',
  '{"Você já ouviu falar de Round 6 na escola? O que os seus amigos contam?","Por que você acha que adultos criaram uma brincadeira de criança onde quem perde morre?","O que uma pessoa pode fazer quando a dívida parece sem saída, antes de tomar uma decisão desesperada?","Se um amigo mostrar um vídeo dessa série no celular, o que você vai fazer?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'Round 6 é para o seu filho? Não. Ficha do pai',
  '18 anos pelo ClassInd e pelo pai. Violência extrema, sexo e desespero bem filmados; virou brincadeira de escola. O que o pai precisa saber e falar.'
)
on conflict (slug) do nothing;

-- Minecraft (2011) · jogo · 629 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'minecraft',
  'Minecraft',
  'Minecraft',
  'jogo',
  2011,
  '{"PC","Nintendo Switch","PlayStation","Xbox","Android","iOS"}'::text[],
  'L',
  '{}'::text[],
  7,
  'Livre pelo ClassInd. Indicamos a partir de 7 anos, e com o chat de servidores públicos desligado até os 12: a idade do jogo é uma, a idade da internet dentro dele é outra. Verificar no portal ClassInd (consulta-jogos).',
  9.0,
  2,
  '{"violencia": 1, "sexo": 0, "linguagem": 0, "drogas": 0, "consumismo": 2, "medo": 2, "valores_positivos": 4, "modelos_positivos": 2, "fe": 0, "mensagem": 3}'::jsonb,
  'O jogo de blocos mais vendido da história: construir, explorar e sobreviver. Excelente para criar, perigoso só quando o pai não configura.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Minecraft é o jogo mais vendido da história e, provavelmente, o primeiro videogame que o seu filho vai pedir com insistência. A boa notícia: é um dos poucos jogos em que a criança passa mais tempo criando do que destruindo. A notícia que exige o pai: o jogo em si é inofensivo, mas o mundo que se conecta a ele pela internet não é. Esta ficha separa as duas coisas."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Um mundo infinito feito de blocos, gerado de forma diferente a cada partida. No modo criativo, o jogador tem materiais ilimitados e constrói o que quiser: casas, castelos, cidades, máquinas. No modo sobrevivência, precisa cortar madeira, minerar, plantar, cozinhar e se proteger dos monstros que aparecem à noite. Dá para jogar sozinho, com a família na mesma rede, em servidores próprios ou em servidores públicos com milhares de desconhecidos. Existe ainda uma versão educacional usada em escolas."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece na tela"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Violência de bloco: zumbis, esqueletos que atiram flechas, aranhas, o creeper que explode e o Ender Dragon no fim. Os monstros somem com um som e soltam itens, sem sangue nem corpo. Animais podem ser abatidos para comida, o que algumas crianças sensíveis evitam. Não há linguagem imprópria no jogo em si; há, e muita, em servidores públicos com chat aberto. O medo vem do escuro e dos barulhos, e crianças de cinco anos às vezes se assustam com o creeper. O consumismo está no Marketplace: skins, texturas e mapas pagos com moeda do jogo comprada com dinheiro de verdade."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Poucas atividades digitais desenvolvem tanto: planejamento, geometria, paciência, resolução de problemas, cooperação. Uma criança que leva três dias construindo uma ponte aprende perseverança de um jeito que nenhuma palestra ensina. O jogo em família, com pai e filho na mesma partida, é uma das melhores formas de estar presente na vida digital do seu filho: você vê o que ele constrói, ele vê que você se interessa. O modo criativo tira toda a tensão e serve para crianças a partir de cinco anos com o pai do lado."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Três elementos interativos que o selo não mostra. O chat com estranhos em servidores públicos, onde aparecem palavrão, assédio e pedidos de contato fora do jogo; a solução é jogar offline, em rede local ou em servidor próprio com convidados conhecidos. As compras no jogo, que viram pedidos semanais de skin nova; a solução é não vincular cartão e decidir junto. E o tempo: o jogo não tem fim nem episódio, então o limite é todo seu. Há ainda o YouTube em volta do jogo, com canais que usam Minecraft para vender outras coisas; é aí que a maioria das crianças descobre conteúdo que o pai não queria."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral +2: positivo, vale jogar junto e comentar. O jogo premia trabalho, criação e cuidado com o que se construiu, e não tem mensagem contrária à família ou à fé. O que falta de bom exemplo humano (não há personagens com história) é compensado pela oportunidade de o pai ser o exemplo dentro do jogo. A régua de uso é a mesma de qualquer ferramenta na oficina: boa nas mãos certas, com supervisão, com hora para parar."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A partir de cinco anos no modo criativo com o pai; a partir de sete no modo sobrevivência, offline ou em rede de casa; servidores públicos com chat só depois dos doze, e mesmo assim com conversa prévia sobre desconhecidos. Para pré-adolescentes, continua sendo uma das melhores opções de jogo, especialmente comparado aos jogos de tiro que chegam na mesma idade. Configure as contas, desligue o chat, defina a hora e jogue junto pelo menos uma vez por semana."}]}]}$body$::jsonb,
  'Minecraft é um mundo de blocos onde o jogador cava, constrói, planta, cria animais e, no modo sobrevivência, enfrenta monstros à noite: zumbis, esqueletos, aranhas e o creeper que explode. A violência é de bloco, sem sangue, e o modo criativo tira os monstros por completo. O que exige o pai são três coisas que não estão no selo: o chat com estranhos em servidores públicos, as compras de skins e mapas dentro do jogo e o tempo, porque o jogo não tem fim. Configurado em casa, com servidor próprio ou modo offline, é uma das melhores ferramentas de criatividade que você pode dar a um filho de sete anos. Solto na internet, é uma porta aberta.',
  '{"O que você construiu hoje? Me mostra e me explica como funciona.","Por que a gente não fala com desconhecido no chat, mesmo que ele pareça ser criança?","Qual é a diferença entre comprar uma skin e construir uma casa que você mesmo fez?","Quando o creeper explodiu a sua construção, o que você fez? Desistiu ou reconstruiu?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'Minecraft é para o seu filho? Ficha do pai',
  'Livre pelo ClassInd, a partir de 7 anos pelo pai, com chat de servidor público desligado. Criatividade, monstros de bloco, compras no jogo. Ficha completa.'
)
on conflict (slug) do nothing;

-- Fortnite (2017) · jogo · 612 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'fortnite',
  'Fortnite',
  'Fortnite',
  'jogo',
  2017,
  '{"PC","PlayStation","Xbox","Nintendo Switch","Android"}'::text[],
  '12',
  '{"violência"}'::text[],
  13,
  '12 anos pelo ClassInd (violência). Nós indicamos 13, com chat de voz fechado e sem cartão vinculado; abaixo disso, não. Verificar no portal ClassInd (consulta-jogos).',
  7.8,
  -1,
  '{"violencia": 3, "sexo": 0, "linguagem": 2, "drogas": 0, "consumismo": 5, "medo": 2, "valores_positivos": 1, "modelos_positivos": 1, "fe": 0, "mensagem": 1}'::jsonb,
  'Cem jogadores caem numa ilha e só um sobrevive. Tiro sem sangue, visual de desenho, chat aberto e a loja de skins mais agressiva do mercado.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fortnite é o jogo que o seu filho de nove anos vai dizer que todo mundo da sala joga. Parte disso é verdade. A outra parte é o que o selo de 12 anos não conta: o jogo é gratuito porque foi desenhado para vender, o chat de voz é aberto por padrão e a estrutura de partidas curtas foi pensada para nunca parar. Esta ficha serve para o pai decidir com informação, não com a pressão do recreio."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "No modo principal, Battle Royale, cem jogadores saltam de um ônibus voador numa ilha, coletam armas e materiais, constroem abrigos em segundos e lutam até restar um ou uma equipe. A ilha encolhe com uma tempestade, forçando o confronto. Há modos sem combate (criativo, shows musicais, mapas feitos pela comunidade) e temporadas que mudam o mapa a cada poucos meses, com personagens de filmes e séries. O jogo roda em console, PC e celular."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece na tela"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Violência de tiro constante, mas estilizada: armas realistas, explosões, nenhuma gota de sangue, o eliminado vira luz e some. É o motivo do selo de 12 anos. O medo é baixo. A linguagem imprópria não está no jogo, está no chat de voz, onde adolescentes e adultos xingam, zombam e às vezes abordam crianças. O consumismo é o ponto máximo da nossa escala: a loja muda todo dia, as skins são exibidas no saguão, o passe de temporada cria urgência e a moeda própria, os V-Bucks, esconde o valor real em reais. Crianças pedem skin como pedem lanche."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "É um jogo de habilidade de verdade: reflexo, estratégia, leitura de mapa, construção sob pressão. Em equipe, exige comunicação e paciência com o colega que erra. Muitos pais que jogam com os filhos relatam que a partida vira momento de conversa. O modo criativo e os mapas da comunidade permitem brincar sem combate. E, diferente de outros jogos de tiro, não há gore, tortura ou violência contra civis."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O chat de voz aberto com desconhecidos, que precisa ser desligado nas configurações de conta de criança. A loja, que transforma o jogo numa vitrine permanente e que já rendeu processo contra a empresa por práticas enganosas com menores; a solução mínima é nenhum cartão vinculado e cada compra decidida pelo pai, de preferência nenhuma. O tempo, porque não existe final de fase; a partida acaba e a próxima começa em segundos. E a frustração: perder é a regra (99 de 100 perdem), e crianças sem maturidade emocional saem da partida gritando. Se isso acontecer na sua casa, não é hora de Fortnite."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral -1: levemente problemático, fácil de corrigir na conversa se a idade for respeitada. Não há mensagem contra a família ou a fé; o problema é de formação. O jogo ensina, sem dizer, que diversão é competir, aparecer e comprar, e que o adversário é alguém a eliminar. Para um adolescente com pai presente, regras claras e outras atividades, é um passatempo como futebol de botão foi para você. Para uma criança de nove anos sozinha no quarto com chat ligado, é um problema."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A partir de treze anos, com conta de criança configurada, chat de voz fechado ou só com amigos conhecidos, sem cartão vinculado e com horário combinado. Abaixo de doze, nossa resposta é não, por mais que a turma jogue; ofereça Minecraft ou um jogo de esporte em família. Pai que joga junto uma vez por semana descobre rápido com quem o filho fala e como ele reage ao perder, e isso vale mais que qualquer bloqueio."}]}]}$body$::jsonb,
  'Fortnite é um jogo de tiro em que cem pessoas pousam numa ilha, procuram armas e se eliminam até sobrar uma. O visual é de desenho animado, não há sangue e os derrotados somem numa luz azul, o que fez a ClassInd marcar 12 anos com o descritor de violência. O problema para o pai não é o tiro, é o resto: o jogo é gratuito e vive de vender skins, danças e passes de temporada com uma pressão constante sobre a criança; o chat de voz coloca o seu filho falando com adultos desconhecidos; e cada partida dura vinte minutos, o que torna o ''só mais uma'' interminável. É um jogo de habilidade e de equipe, com mérito, para quem tem idade e regras.',
  '{"Você joga com quem? Conhece essas pessoas fora do jogo?","Por que você acha que o jogo é de graça e as roupas custam dinheiro?","O que você sente quando perde uma partida no fim? E quando ganha?","Se alguém no chat falar uma coisa estranha ou pedir para conversar fora do jogo, o que você faz?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'Fortnite é para o seu filho? Ficha do pai',
  '12 anos pelo ClassInd, 13 pelo pai, com chat fechado e sem cartão. Tiro sem sangue, loja agressiva, chat com estranhos. O que o pai precisa saber.'
)
on conflict (slug) do nothing;

-- YouTube Kids (2015) · app · 570 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'youtube-kids',
  'YouTube Kids',
  'YouTube Kids',
  'app',
  2015,
  '{"Android","iOS","TV"}'::text[],
  'L',
  '{}'::text[],
  4,
  'Livre pelo ClassInd (classificação de aplicativo). Indicamos a partir de 4 anos e só no modo com canais aprovados pelo pai: no modo automático, o filtro deixa passar coisa que você não quer. Verificar no portal ClassInd (consulta-jogos).',
  6.8,
  0,
  '{"violencia": 1, "sexo": 0, "linguagem": 1, "drogas": 0, "consumismo": 4, "medo": 1, "valores_positivos": 2, "modelos_positivos": 1, "fe": 0, "mensagem": 1}'::jsonb,
  'A versão infantil do YouTube: melhor que o YouTube aberto, pior que uma lista escolhida pelo pai. Funciona bem só com os canais aprovados à mão.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "YouTube Kids é o aplicativo que a maioria dos pais instala como solução e descobre, meses depois, que era só um filtro grosso. Ele é de fato melhor que o YouTube aberto, e isso basta para muita gente. Para o pai que quer saber o que o filho assiste, a pergunta certa é outra: o que entra pelo filtro automático e como fechar a porta."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "É uma versão do YouTube com interface simplificada, perfis por criança, três faixas etárias e um conjunto de vídeos selecionados por algoritmo e por revisão parcial. Não há comentários, não há transmissão ao vivo, e o pai pode definir tempo de uso, bloquear vídeos e canais, desligar a busca e, no recurso mais importante, limitar o perfil a conteúdo aprovado manualmente. O aplicativo é gratuito e vive de anúncios."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece na tela"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Depende inteiramente do modo. No automático, a maior parte é desenho, música infantil, vídeos de brinquedo e canais de 'família' que filmam o dia a dia dos filhos. O filtro já deixou passar, em episódios conhecidos, vídeos com violência e temas adultos disfarçados com personagens infantis, e canais com humor vulgar para a faixa de oito a doze anos. A violência e o medo que aparecem são baixos, mas não são zero. O consumismo é alto: anúncios antes dos vídeos e, pior, vídeos inteiros que são propaganda sem parecer (abertura de caixa de brinquedo, 'desafio' com produto, canal de marca)."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Há conteúdo excelente dentro dele quando o pai escolhe: canais de ciência para crianças, músicas de roda, desenhos clássicos, contação de histórias, catequese infantil, canais de marcenaria e de culinária que pai e filho assistem juntos. O cronômetro funciona e encerra o aplicativo com uma tela amigável. O modo de conteúdo aprovado permite montar, em uma hora de configuração, uma 'TV' particular da sua família. Comparado ao YouTube aberto, elimina comentários, recomendações adultas e transmissões ao vivo."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "A esteira: o próximo vídeo começa sozinho, e a criança de quatro anos não tem freio para isso; desligue a reprodução automática. A propaganda disfarçada, que ensina a desejar antes de ensinar qualquer outra coisa. Os canais de 'família' que expõem crianças reais como entretenimento, um padrão que vale conversar com filhos mais velhos. E a falsa segurança: o nome 'Kids' faz o pai relaxar, e é justamente aí que o algoritmo escolhe por você. A regra prática é a mesma da televisão antiga: o aparelho fica na sala, não no quarto."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral 0: neutro, porque o aplicativo é uma prateleira e o que ele entrega depende de quem arruma a prateleira. Não há nada contrário à família na ferramenta; há muito no que ela recomenda sozinha. Um pai que configura o modo aprovado, escolhe canais, desliga a reprodução automática e assiste junto de vez em quando transforma o aplicativo em coisa boa. O que não existe é versão neutra sem trabalho do pai."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Abaixo de dois anos, nada de tela, recomendação dos pediatras que a gente endossa. De dois a quatro, só vídeos escolhidos pelo pai e assistidos junto, por pouco tempo. A partir de quatro, no modo aprovado, com cronômetro e aparelho na sala. A partir de oito, a criança vai pedir o YouTube normal; segure o quanto puder e, quando liberar, faça junto, com conta supervisionada."}]}]}$body$::jsonb,
  'YouTube Kids é um aplicativo separado, com vídeos filtrados por idade (pré-escolar, mais novos, mais velhos), controle de tempo e sem comentários. É melhor que deixar o filho no YouTube normal, e esse é o elogio inteiro. O filtro automático é feito por máquina e já deixou passar vídeos impróprios disfarçados de desenho, o que a própria empresa admitiu. A propaganda é constante, tanto em anúncios quanto em vídeos de unboxing e ''review'' de brinquedo feitos para vender. O recurso que salva o aplicativo é o modo ''só conteúdo aprovado'', em que você escolhe canais e vídeos à mão e o filho só vê aquilo. Com esse modo e o cronômetro ligado, vira uma ferramenta razoável. Sem ele, é a mesma esteira infinita do YouTube com cores mais vivas.',
  '{"Qual vídeo você viu hoje? Me conta do que era.","Esse canal está tentando te vender alguma coisa? Como você percebe?","Por que a gente combina um tempo e desliga mesmo no meio do vídeo?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'YouTube Kids é para o seu filho? Ficha do pai',
  'Livre, a partir de 4 anos, só no modo com canais aprovados pelo pai. Filtro automático falha, propaganda constante, esteira sem fim. Como configurar.'
)
on conflict (slug) do nothing;

-- O Pequeno Príncipe (1943) · livro · 630 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'o-pequeno-principe',
  'O Pequeno Príncipe',
  'Le Petit Prince',
  'livro',
  1943,
  '{"Livro físico","Kindle"}'::text[],
  null,
  '{}'::text[],
  7,
  'Livros não recebem Classificação Indicativa. Indicamos leitura em voz alta pelo pai a partir de 7 anos e leitura sozinho a partir de 10: o texto é simples, as ideias não são.',
  9.4,
  3,
  '{"violencia": 0, "sexo": 0, "linguagem": 0, "drogas": 1, "consumismo": 1, "medo": 2, "valores_positivos": 5, "modelos_positivos": 3, "fe": 3, "mensagem": 5}'::jsonb,
  'Um aviador perdido no deserto conhece um menino de outro planeta. Amizade, responsabilidade e o que os olhos não veem, em um livro para ler junto.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "O Pequeno Príncipe é o livro que todo mundo diz que leu e poucos pais leram com os filhos. É pena, porque foi feito para isso: um adulto, o aviador, e um menino, o príncipe, conversando sobre o que importa, com desenhos no meio. Ler em voz alta, duas ou três noites, é uma das experiências de paternidade mais simples e mais fundas que existem."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata, sem contar o fim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Um piloto cai com o avião no deserto do Saara e, enquanto tenta consertar o motor, encontra um menino que pede um desenho de carneiro. O menino vem de um asteroide pequeno onde mora com três vulcões e uma rosa. Ele conta como deixou a rosa, os planetas que visitou (um rei sem súditos, um vaidoso, um bêbado, um homem de negócios, um acendedor de lampiões, um geógrafo) e como chegou à Terra, onde uma raposa lhe ensina o que é amizade e uma serpente promete mandá-lo de volta. O livro termina no deserto, com o aviador e o menino, de um jeito que cada leitor entende à sua maneira."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece no texto"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nenhuma violência, sensualidade ou palavrão. O bêbado do quarto planeta rende uma conversa sobre vício: ele bebe para esquecer que tem vergonha de beber, e a criança percebe o círculo sem precisar de explicação. A serpente e a cena final são o único ponto que assusta: o texto sugere a morte do menino sem afirmar, e crianças de sete anos perguntam. Responda com o que o próprio livro oferece: o corpo era pesado demais para a viagem, e o que importava nele não era o corpo. A rosa é vaidosa e exigente, mas o livro ensina a cuidar dela mesmo assim."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "O livro inteiro é uma lição de responsabilidade. A raposa diz que você se torna eternamente responsável por aquilo que cativa, e essa frase, lida pelo pai, vira regra de casa: o cachorro, o irmão menor, o amigo, a namorada daqui a dez anos. Os planetas são retratos do adulto que perdeu o essencial: poder sem ninguém para servir, vaidade sem obra, bebida, dinheiro acumulado sem uso, trabalho sem sentido, conhecimento sem experiência. E a frase de que o essencial é invisível aos olhos abre a porta para falar de alma, de Deus e de amor sem forçar nada."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Pouco. O livro trata os adultos como gente que esqueceu o que importa, e uma criança pode usar isso como argumento contra o pai; é só rir e concordar em parte. A morte em aberto no fim pede o pai perto, não pela violência, que não há, mas pela pergunta. Há edições com texto adaptado e ilustrações novas; prefira a tradução integral com os desenhos originais de Saint-Exupéry, porque os desenhos fazem parte da história."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral +3: muito positivo. Saint-Exupéry era um homem de formação católica escrevendo durante a guerra, longe da esposa, e o livro carrega isso: fidelidade a quem se ama mesmo quando é difícil, cuidado com o pequeno, desprezo pelo poder e pelo dinheiro vazios, e a intuição de que o visível não esgota o real. A cena da raposa é quase uma catequese sobre amizade e compromisso. Não há nada a corrigir, só a aprofundar."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Leia em voz alta a partir de sete anos, um capítulo por noite, parando nos desenhos. Deixe ler sozinho a partir de dez. Releia com o adolescente aos quinze, quando a rosa vai significar outra coisa. E leia você, pai, de novo, antes de começar: o livro muda conforme a idade de quem lê, e é bem possível que o aviador tenha mais a dizer a você do que ao seu filho."}]}]}$body$::jsonb,
  'É um livro curto, ilustrado pelo próprio autor, que se lê em duas noites e se entende ao longo da vida. A história tem um piloto caído no deserto e um menino que deixou o planeta dele por causa de uma rosa exigente. Não há violência, sexo ou linguagem imprópria. Há um bêbado que bebe para esquecer a vergonha de beber (um dos planetas visitados), uma raposa que ensina o que significa cativar, e um final com uma picada de serpente que o texto deixa em aberto e que faz criança perguntar se o menino morreu. Para o pai, é a melhor introdução que existe a dois temas: você é responsável para sempre por aquilo que cativa, e o essencial é invisível aos olhos.',
  '{"O que a raposa quis dizer com cativar? Quem você já cativou e por quem você é responsável?","Por que o pequeno príncipe cuidava da rosa mesmo ela sendo chata com ele?","O homem de negócios contava estrelas para ser dono delas. De que adianta ser dono de uma coisa que a gente não cuida?","O que você acha que aconteceu com o pequeno príncipe no fim? Por que o livro não conta direito?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'O Pequeno Príncipe é para o seu filho? Ficha do pai',
  'Sem ClassInd (livro). Ler junto a partir de 7 anos, sozinho a partir de 10. Amizade, responsabilidade, uma morte em aberto. O que conversar com seu filho.'
)
on conflict (slug) do nothing;

-- O Leão, a Feiticeira e o Guarda-Roupa (1950) · livro · 662 palavras
insert into public.media_reviews (slug, title, original_title, type, year, platforms, classind, classind_descriptors, pai_age_min, pai_age_note, score_quality, score_moral, content_scores, summary, body, what_parents_need_to_know, talk_with_your_kids, poster_url, poster_credit, poster_license, affiliate_url, status, publish_at, author_id, seo_title, seo_description)
values (
  'o-leao-a-feiticeira-e-o-guarda-roupa',
  'O Leão, a Feiticeira e o Guarda-Roupa',
  'The Lion, the Witch and the Wardrobe',
  'livro',
  1950,
  '{"Livro físico","Kindle"}'::text[],
  null,
  '{}'::text[],
  8,
  'Livros não recebem Classificação Indicativa. Indicamos leitura em voz alta a partir de 8 anos e sozinho a partir de 10. O filme de 2005 tem classificação própria no ClassInd; esta ficha é do livro.',
  9.5,
  4,
  '{"violencia": 2, "sexo": 0, "linguagem": 0, "drogas": 0, "consumismo": 0, "medo": 3, "valores_positivos": 5, "modelos_positivos": 5, "fe": 5, "mensagem": 5}'::jsonb,
  'Quatro irmãos atravessam um guarda-roupa e chegam a Nárnia, onde um leão se sacrifica por um traidor. A melhor alegoria cristã já escrita para crianças.',
  $body${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "C. S. Lewis escreveu este livro para que uma criança sentisse, antes de entender, o que significa alguém inocente morrer no lugar de um culpado e voltar. Se você quer que o seu filho entenda a Páscoa com o coração e não só com a cabeça, não existe atalho melhor do que ler Nárnia em voz alta, um capítulo por noite, começando por este."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Do que trata, sem contar o fim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Durante a Segunda Guerra, quatro irmãos, Pedro, Susana, Edmundo e Lúcia, são mandados para a casa de um professor no interior da Inglaterra. Lúcia descobre que um guarda-roupa dá para Nárnia, uma terra onde é sempre inverno e nunca Natal por causa da Feiticeira Branca. Edmundo, invejoso da irmã, encontra a Feiticeira primeiro, come os doces turcos dela e promete trazer os irmãos. Quando os quatro chegam juntos, Aslan, o leão que é o verdadeiro rei de Nárnia, está voltando, e a traição de Edmundo tem um preço que alguém precisa pagar."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que aparece no texto"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Violência moderada e com propósito: a batalha final é contada em poucas páginas, sem detalhe de ferimento, e a morte de Aslan na Mesa de Pedra é a cena mais pesada, com o leão amarrado, tosquiado, zombado e morto diante de uma multidão de monstros. Lewis descreve sem sangue, mas não suaviza a humilhação. A Feiticeira transforma criaturas em pedra e manda matar o fauno Tumnus. Não há sensualidade nem linguagem imprópria. O medo vem da Feiticeira, dos lobos da polícia secreta e da noite da Mesa de Pedra; crianças de seis anos costumam pedir para parar ali e continuar de manhã."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que tem de bom"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tudo. Edmundo é o personagem mais importante para o pai: ele não trai por maldade pura, mas por inveja, orgulho ferido e gula, exatamente como a gente peca, e o livro mostra como um pecado pequeno vira um grande sem que a pessoa perceba. O perdão de Aslan é dado antes de ser merecido e o menino muda de verdade. Pedro aprende a ser homem assumindo responsabilidade pelo irmão. Lúcia é a fé que acredita antes de ver. E a frase do senhor Castor sobre Aslan, que não é manso mas é bom, corrige em uma linha a imagem de um Deus bonzinho e sem exigência."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "O que preocupa"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Quase nada. A morte de Aslan pede o pai perto, não para proteger a criança da cena, mas para ajudá-la a esperar o que vem depois. O Papai Noel aparece dando presentes que são armas, o que confunde alguns leitores; explique que em Nárnia ele é o sinal de que o inverno está acabando. Algumas edições brasileiras trazem o volume na ordem cronológica, começando pelo Sobrinho do Mago; para a primeira leitura com os filhos, comece por este, que foi o primeiro escrito."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Visão do pai católico"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nota moral +4: edificante. O livro é uma alegoria explícita da Paixão e da Ressurreição, escrita por um cristão que sabia o que estava fazendo: o inocente que morre pelo traidor, a Mesa de Pedra que se parte, as mulheres que encontram o túmulo vazio, o rei que volta e restaura a terra. Mas funciona como aventura mesmo para quem não enxerga a alegoria, e por isso serve para o filho de oito anos que só quer saber se Edmundo vai se salvar. Depois da leitura, a Semana Santa nunca mais é a mesma para a criança."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Para quem é e para quem ainda não é"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Em voz alta a partir de oito anos, com crianças de seis acompanhando se o pai souber dosar a noite da Mesa de Pedra. Sozinho a partir de dez. Os outros seis livros da série seguem na mesma faixa, com O Cavalo e seu Menino e A Última Batalha um pouco mais exigentes. O filme de 2005 é fiel e bem feito, mas a batalha é mais longa e visual; veja depois de ler, nunca antes, e confira a classificação dele no portal do ClassInd."}]}]}$body$::jsonb,
  'É o livro de aventura que todo pai católico deveria ler para os filhos, porque faz, com um leão e uma feiticeira, o que a catequese tenta fazer com palavras: mostra traição, sacrifício, perdão e ressurreição numa história que a criança pede para continuar. Há batalha no fim e a morte de Aslan na Mesa de Pedra, descrita com sobriedade mas com peso: ele é humilhado, amarrado e morto por uma multidão de criaturas, enquanto duas meninas assistem escondidas. Não há sensualidade nem linguagem imprópria. A Feiticeira Branca assusta de verdade, e a traição de Edmundo por doces turcos é o retrato mais honesto do pecado que uma criança vai encontrar num livro de aventura.',
  '{"Por que o Edmundo traiu os irmãos? Ele queria mesmo fazer mal ou só queria os doces?","O Aslan morreu no lugar do Edmundo. Você conhece alguma outra história em que alguém morreu no lugar dos outros?","O que mudou no Edmundo depois que ele foi perdoado?","O senhor Castor diz que o Aslan não é manso, mas é bom. Qual é a diferença?"}'::text[],
  null,
  null,
  null,
  null,
  'published',
  now(),
  (select id from public.profiles where id = 'e8bb17c5-ce46-4d2c-bda7-4d86d975f6fa' limit 1),
  'O Leão, a Feiticeira e o Guarda-Roupa: ficha do pai',
  'Sem ClassInd (livro). Ler junto a partir de 8 anos. Traição, sacrifício de Aslan e ressurreição: a melhor alegoria cristã para crianças. O que conversar.'
)
on conflict (slug) do nothing;
